const body = $json.body || {};
const tally = body.data && Array.isArray(body.data.fields);
let raw;
let resolved = null;
if (tally) {
  const f = {};
  for (const field of body.data.fields) {
    let v = field.value;
    if (Array.isArray(v) && Array.isArray(field.options)) {
      v = v.map(id => (field.options.find(o => o.id === id) || {}).text).filter(Boolean).join(', ');
    }
    f[field.label] = v;
  }
  resolved = f;
  raw = {
    order_id: f['order_id'], customer_name: f['Full Name'], email: f['Email'],
    product: f['Product'], quantity: f['Quantity'], price: null,
    shipping_address: f['Shipping Address'], order_date: body.data.createdAt,
  };
  const m = String(raw.product || '').match(/^(.*?),\s*CHF\s*([\d.]+)\s*$/);
  if (m) { raw.product = m[1]; raw.price = m[2]; }
} else {
  raw = {
    order_id: body.order_id ?? body.orderId, customer_name: body.customer_name ?? body.customerName,
    email: body.email, product: body.product ?? body.product_name, quantity: body.quantity,
    price: body.price, shipping_address: body.shipping_address ?? body.shippingAddress,
    order_date: body.order_date ?? body.date,
  };
}

const text = v => (v === undefined || v === null) ? '' : String(v).replace(/\s+/g, ' ').trim();
const orderId = text(raw.order_id).toUpperCase();
const customerName = text(raw.customer_name);
const email = text(raw.email).toLowerCase();
const product = text(raw.product);
const shippingAddress = String(raw.shipping_address ?? '').split(/\n+/).map(l => text(l).replace(/,+$/, '')).filter(Boolean).join(', ');
const qtyText = text(raw.quantity);
const priceText = text(raw.price).replace(/^CHF\s*/i, '');

const missing = [];
if (!orderId) missing.push('Order ID');
if (!customerName) missing.push('Customer Name');
if (!email) missing.push('Email');
if (!product) missing.push('Product');
if (!qtyText) missing.push('Quantity');
if (!priceText) missing.push('Price');
if (!shippingAddress) missing.push('Shipping Address');

const invalid = [];
if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) invalid.push('Email "' + email + '" is not a valid address');
const quantity = Number(qtyText);
if (qtyText && (!Number.isInteger(quantity) || quantity < 1)) invalid.push('Quantity "' + qtyText + '" is not a whole number above 0');
const unitPrice = Number(priceText);
if (priceText && (!Number.isFinite(unitPrice) || unitPrice <= 0)) invalid.push('Price "' + priceText + '" is not a valid amount');

const when = raw.order_date ? DateTime.fromISO(String(raw.order_date)) : null;
const orderDate = (when && when.isValid ? when : $now).setZone('Europe/Zurich').toFormat('yyyy-MM-dd HH:mm');

const problems = [];
if (missing.length) problems.push('Missing: ' + missing.join(', '));
problems.push(...invalid);

return { json: {
  orderId, orderDate, customerName, email, product,
  quantity: Number.isInteger(quantity) ? quantity : qtyText,
  unitPrice: Number.isFinite(unitPrice) ? Math.round(unitPrice * 100) / 100 : priceText,
  total: problems.length ? '' : Math.round(quantity * unitPrice * 100) / 100,
  shippingAddress,
  valid: problems.length === 0,
  errorType: missing.length ? 'Missing Fields' : (invalid.length ? 'Invalid Data' : ''),
  problems: problems.join('. '),
  orderData: JSON.stringify(resolved || body),
} };

const o = $('Clean And Validate Order').first().json;
const now = $now.setZone('Europe/Zurich').toFormat('yyyy-MM-dd HH:mm');
let errorType = o.errorType;
let details = o.problems;

if ($json.error) {
  const e = $json.error;
  const message = (typeof e === 'string' ? e : (e.description || e.message)) || 'Unknown error';
  const step = $('Send Order Confirmation').isExecuted ? 'Customer confirmation email'
    : $('Email Order Summary To Owner').isExecuted ? 'Owner notification email'
    : $('Save Order').isExecuted ? 'Saving the order to the sheet'
    : 'Checking for a duplicate order';
  const saved = $('Save Order').isExecuted && step !== 'Saving the order to the sheet';
  errorType = 'Step Failed';
  details = step + ' failed: ' + message + '. ' + (saved ? 'The order IS saved on the Orders tab.' : 'The order was NOT saved.');
} else if (o.valid) {
  const existing = $json;
  errorType = 'Duplicate Order';
  details = 'Order ' + o.orderId + ' is already on the Orders tab (saved ' + (existing['Date'] || 'earlier') + '). This copy was not saved again.';
}

const row = (k, v) => '<tr><td style="padding:6px 10px;color:#6b7280;width:150px;vertical-align:top">' + k + '</td><td style="padding:6px 10px">' + (v === '' || v === undefined ? '-' : v) + '</td></tr>';
const alertHtml = '<div style="font-family:Arial,sans-serif;font-size:14px;color:#1f2a37;max-width:620px">'
  + '<div style="background:#9b1c1c;color:#fff;padding:12px 16px;font-weight:bold">Order Needs Attention: ' + errorType + '</div>'
  + '<p style="margin:10px 0">' + details + '</p>'
  + '<table style="border-collapse:collapse;width:100%">'
  + row('Order ID', o.orderId) + row('Customer', o.customerName) + row('Email', o.email)
  + row('Product', o.product) + row('Quantity', o.quantity) + row('Ship To', o.shippingAddress)
  + '</table><p style="margin:14px 0 0">Logged on the Errors tab with the full order data. <a href="YOUR_GOOGLE_SHEET_URL">Open the order sheet</a></p></div>';

return { json: {
  loggedAt: now, orderId: o.orderId || '(none)', customerName: o.customerName, email: o.email,
  errorType, details, orderData: o.orderData,
  alertSubject: 'Order Needs Attention: ' + (o.orderId || 'no order ID') + ' (' + errorType + ')',
  alertHtml,
} };

const o = $('Clean And Validate Order').first().json;
const chf = n => 'CHF ' + Number(n).toFixed(2);
const row = (k, v) => '<tr><td style="padding:6px 10px;color:#6b5e55;width:150px;vertical-align:top">' + k + '</td><td style="padding:6px 10px">' + v + '</td></tr>';
const firstName = o.customerName.split(' ')[0];

const ownerHtml = '<div style="font-family:Arial,sans-serif;font-size:14px;color:#2b2420;max-width:620px">'
  + '<div style="background:#8c543d;color:#fff;padding:12px 16px;font-weight:bold">New Order ' + o.orderId + '</div>'
  + '<table style="border-collapse:collapse;width:100%;margin-top:8px">'
  + row('Order ID', o.orderId) + row('Date', o.orderDate) + row('Customer', o.customerName) + row('Email', o.email)
  + row('Product', o.product) + row('Quantity', o.quantity) + row('Unit Price', chf(o.unitPrice))
  + row('Total', '<b>' + chf(o.total) + '</b>') + row('Ship To', o.shippingAddress) + row('Status', 'New')
  + '</table><p style="margin:14px 0 0"><a href="YOUR_GOOGLE_SHEET_URL">Open the order sheet</a></p></div>';

const customerHtml = '<div style="font-family:Georgia,serif;font-size:15px;color:#2b2420;max-width:560px;line-height:1.5">'
  + '<p style="font-size:20px;margin:0 0 14px">Brindle &amp; Kiln</p>'
  + '<p>Hi ' + firstName + ',</p>'
  + '<p>Thank you for your order. Every piece is made by hand in our Geneva studio, and yours is now in the queue.</p>'
  + '<table style="border-collapse:collapse;width:100%;font-family:Arial,sans-serif;font-size:14px;background:#f7f2ee">'
  + row('Order', o.orderId) + row('Item', o.quantity + ' x ' + o.product) + row('Total', chf(o.total)) + row('Shipping To', o.shippingAddress)
  + '</table>'
  + '<p>We will email you again as soon as it is on its way. If anything looks wrong, just reply to this email.</p>'
  + '<p>Warm regards,<br>The Brindle &amp; Kiln Studio</p></div>';

return { json: {
  ownerSubject: 'New Order ' + o.orderId + ': ' + o.quantity + ' x ' + o.product + ' (' + chf(o.total) + ')',
  ownerHtml,
  customerTo: o.email,
  customerSubject: 'Thank you for your order, ' + firstName + ' (' + o.orderId + ')',
  customerHtml,
} };
